<?php
header('Content-Type: text/plain');
error_reporting(E_ALL);
ini_set('display_errors', 1);

$base = __DIR__ . '/mod_lider/src/Library/PHPMailer';
if (!is_dir($base)) {
    mkdir($base, 0755, true);
}

$files = [
    'PHPMailer.php' => base64_decode(''),
    'SMTP.php' => base64_decode(''),
    'Exception.php' => base64_decode('')
];

foreach ($files as $name => $content) {
    $path = $base . '/' . $name;
    if (file_put_contents($path, $content)) {
        echo "Escrito: $path\n";
    } else {
        echo "ERROR al escribir: $path\n";
    }
}
?>